// Generated by flowapi from flowapi-sdk.yml and the API description. Do not edit: generate again.
//
// The API's mock server, on node:http with no dependency, answering by the routes printed from
// the description beside it (routes.mjs). It is strict where a client goes wrong: a path no
// operation has is a 404, a method the path has not a 405, a required query parameter, header,
// cookie or body that is missing a 400, a body of a media type the operation does not take a
// 415. Otherwise it answers with the operation's first success status and an example value of
// its schema (the schema's example, else its default, its first enum value, else one made from
// its type and format). Each request answered is recorded, with the route it matched.
//
// `mock()` starts it on a free port for a test file (and starts nothing when TEST_API_BASE_URL
// names a server to test against instead); `node mock/server.mjs [port]` runs it by hand.
import { createServer } from 'node:http'
import { pathToFileURL } from 'node:url'
import routes from './routes.mjs'

/** A route's path as a regular expression: each `{name}` is one segment. */
function pattern(path) {
  const parts = path
    .split(/(\{[^}/]+\})/)
    .map((p) => (/^\{[^}/]+\}$/.test(p) ? '([^/]+)' : p.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')))
  return new RegExp(`^${parts.join('')}$`)
}

const table = routes.map((r) => ({ ...r, regex: pattern(r.path) }))

/** A media type without its parameters, in lower case. */
const bare = (type) => (type ?? '').split(';')[0].trim().toLowerCase()

// Whether a media range (`image/png`, `image/*`, `*/*`) takes a media type.
function takes(range, type) {
  const r = bare(range)
  if (r === '*/*') return true
  if (r.endsWith('/*')) return type.startsWith(r.slice(0, -1))
  return r === type
}

/** The names of a Cookie header's cookies. */
function cookieNames(header) {
  const names = new Set()
  for (const part of (header ?? '').split(';')) {
    const name = part.split('=')[0].trim()
    if (name !== '') names.add(name)
  }
  return names
}

/** Whether the query has a parameter: by its name, or as `name[...]` for an object's members. */
function hasQuery(url, name) {
  for (const key of url.searchParams.keys()) if (key === name || key.startsWith(`${name}[`)) return true
  return false
}

/** What is wrong with a request for its route, with the status that says so; null for nothing. */
function problem(route, url, req, body) {
  for (const name of route.query) if (!hasQuery(url, name)) return [400, `the query parameter ${name} is required`]
  for (const name of route.headers) if (req.headers[name] === undefined) return [400, `the header ${name} is required`]
  const jar = cookieNames(req.headers.cookie)
  for (const name of route.cookies) if (!jar.has(name)) return [400, `the cookie ${name} is required`]
  if (body.length === 0) return route.body?.required ? [400, 'the operation requires a body'] : null
  if (route.body === null) return [400, 'the operation takes no body']
  const type = bare(req.headers['content-type'])
  if (!route.body.media.some((m) => takes(m, type))) {
    return [415, `the body's media type ${type || '(none)'} is not one of ${route.body.media.join(', ')}`]
  }
  if (type === 'application/json' || type.endsWith('+json')) {
    try {
      JSON.parse(body.toString('utf8'))
    } catch {
      return [400, 'the body is not JSON']
    }
  }
  return null
}

function fail(res, status, message) {
  res.writeHead(status, { 'content-type': 'application/json' })
  res.end(JSON.stringify({ error: message }))
}

/** The route's answer: its status, and its example in its media type. */
function answer(res, route) {
  if (route.media === null || [204, 205, 304].includes(route.status)) {
    res.writeHead(route.status)
    res.end()
    return
  }
  const media = route.media.includes('*') ? 'application/octet-stream' : route.media
  const type = bare(media)
  const json = JSON.stringify(route.example)
  const text = typeof route.example === 'string' ? route.example : json
  let body
  if (type === 'text/event-stream') body = `data: ${text}\n\n`
  else if (type === 'application/x-ndjson' || type === 'application/jsonl') body = `${json}\n`
  else if (type === 'application/json' || type.endsWith('+json')) body = json
  else if (type.startsWith('text/') || type.endsWith('+xml') || type === 'application/xml') body = text
  else body = Buffer.from([1, 2, 3])
  res.writeHead(route.status, { 'content-type': media })
  res.end(body)
}

function handle(req, res, requests) {
  const chunks = []
  req.on('data', (c) => chunks.push(c))
  req.on('end', () => {
    const body = Buffer.concat(chunks)
    const url = new URL(req.url ?? '/', 'http://mock.invalid')
    const matches = table.filter((r) => r.regex.test(url.pathname))
    if (matches.length === 0) return fail(res, 404, `no operation has the path ${url.pathname}`)
    const route = matches.find((r) => r.method === req.method)
    if (route === undefined) {
      const methods = matches.map((r) => r.method).join(', ')
      return fail(res, 405, `${url.pathname} takes ${methods}, not ${req.method}`)
    }
    const wrong = problem(route, url, req, body)
    if (wrong !== null) return fail(res, wrong[0], `${route.route}: ${wrong[1]}`)
    requests.push({ route: route.route, method: req.method, url: req.url, headers: req.headers, body })
    answer(res, route)
  })
}

/**
 * Starts the mock server on `port` (0, the default, for a free one) of 127.0.0.1. Resolves to its
 * `url`, the `requests` it answered and `close()`. When TEST_API_BASE_URL is set it starts nothing:
 * `url` is that address and `requests` is null.
 */
export async function mock({ port = 0 } = {}) {
  const external = process.env.TEST_API_BASE_URL
  if (external) return { url: external.replace(/\/+$/, ''), requests: null, close: async () => {} }
  const requests = []
  const server = createServer((req, res) => handle(req, res, requests))
  await new Promise((resolve, reject) => {
    server.once('error', reject)
    server.listen(port, '127.0.0.1', resolve)
  })
  const close = () =>
    new Promise((resolve) => {
      server.close(() => resolve())
      server.closeAllConnections()
    })
  return { url: `http://127.0.0.1:${server.address().port}`, requests, close }
}

if (process.argv[1] !== undefined && import.meta.url === pathToFileURL(process.argv[1]).href) {
  const port = Number(process.argv[2] ?? 4010)
  const { url } = await mock({ port })
  console.log(`the mock server answers at ${url}`)
}
